    }
}

public class Main {
    static volatile boolean running = true;

    public static void main(String[] args) throws InterruptedException {
        Thread worker = new Thread(() -> {
            while (running) {
                // busy wait until the flag flips
            }
            System.out.println("stopped");
        });
        worker.start();
        Thread.sleep(100);
        running = false;
        worker.join();
        System.out.println("main done");
    }
}

public class Main {
    static final Object LOCK_A = new Object();
    static final Object LOCK_B = new Object();

    static void transferAB() {
        synchronized (LOCK_A) {
            synchronized (LOCK_B) {
                System.out.println("AB");
            }
        }
    }

    static void transferBA() {
        synchronized (LOCK_A) {
            synchronized (LOCK_B) {
                System.out.println("BA");
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
        Thread t1 = new Thread(Main::transferAB);
        Thread t2 = new Thread(Main::transferBA);
        t1.start();
        t2.start();
        t1.join();
        t2.join();
        System.out.println("finished");
    }
}

import java.util.concurrent.Callable;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class Main {
    public static void main(String[] args) throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(3);
        try {
            Callable<Integer>[] tasks = new Callable[] {
                (Callable<Integer>) () -> 100,
                (Callable<Integer>) () -> 200,
                (Callable<Integer>) () -> 300
            };
            int total = 0;
            for (Callable<Integer> task : tasks) {
                Future<Integer> future = pool.submit(task);
                total += future.get();
            }
            System.out.println("total=" + total);
        } finally {
            pool.shutdown();
        }
    }
}

